public static class DeskTheme {
 public static Color Ink=Color.FromArgb(25,30,30), Paper=Color.FromArgb(246,243,227), Lime=Color.FromArgb(222,255,40), Muted=Color.FromArgb(158,162,142);
 static string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ /";
 static string[] glyphs={"01110/10001/10001/11111/10001/10001/10001","11110/10001/10001/11110/10001/10001/11110","01111/10000/10000/10000/10000/10000/01111","11110/10001/10001/10001/10001/10001/11110","11111/10000/10000/11110/10000/10000/11111","11111/10000/10000/11110/10000/10000/10000","01111/10000/10000/10111/10001/10001/01111","10001/10001/10001/11111/10001/10001/10001","11111/00100/00100/00100/00100/00100/11111","00111/00010/00010/00010/10010/10010/01100","10001/10010/10100/11000/10100/10010/10001","10000/10000/10000/10000/10000/10000/11111","10001/11011/10101/10101/10001/10001/10001","10001/11001/11001/10101/10011/10011/10001","01110/10001/10001/10001/10001/10001/01110","11110/10001/10001/11110/10000/10000/10000","01110/10001/10001/10001/10101/10010/01101","11110/10001/10001/11110/10100/10010/10001","01111/10000/10000/01110/00001/00001/11110","11111/00100/00100/00100/00100/00100/00100","10001/10001/10001/10001/10001/10001/01110","10001/10001/10001/10001/10001/01010/00100","10001/10001/10001/10101/10101/11011/10001","10001/10001/01010/00100/01010/10001/10001","10001/10001/01010/00100/00100/00100/00100","11111/00001/00010/00100/01000/10000/11111","00000/00000/00000/00000/00000/00000/00000","00001/00010/00010/00100/01000/01000/10000"};
 public static void Title(Graphics g,string text,int x,int y,int scale){using(var brush=new SolidBrush(Paper))foreach(char c in text.ToUpperInvariant()){int index=alphabet.IndexOf(c);if(index>=0){string[] rows=glyphs[index].Split('/');for(int r=0;r<7;r++)for(int col=0;col<5;col++)if(rows[r][col]=='1')g.FillRectangle(brush,x+col*scale,y+r*scale,scale,scale);}x+=6*scale;}}
 public static void Frame(Graphics g,Rectangle r,Color fill,Color edge){using(var b=new SolidBrush(fill)){g.FillRectangle(b,r.X+3,r.Y,r.Width-6,r.Height);g.FillRectangle(b,r.X,r.Y+3,r.Width,r.Height-6);}using(var p=new Pen(edge)){g.DrawLine(p,r.X+3,r.Y,r.Right-4,r.Y);g.DrawLine(p,r.X+3,r.Bottom-1,r.Right-4,r.Bottom-1);g.DrawLine(p,r.X,r.Y+3,r.X,r.Bottom-4);g.DrawLine(p,r.Right-1,r.Y+3,r.Right-1,r.Bottom-4);}}
 public static void Apply(Control root){foreach(Control c in root.Controls){if(c is TextBox){var t=(TextBox)c;t.BackColor=Paper;t.ForeColor=Ink;t.BorderStyle=BorderStyle.FixedSingle;t.Margin=new Padding(4);}
 if(c is Label){c.ForeColor=Ink;if(c.Parent is TableLayoutPanel){c.BackColor=Ink;c.ForeColor=Paper;c.Font=new Font("Microsoft YaHei UI",9,FontStyle.Bold);}}
 if(c is NumericUpDown||c is ComboBox){c.BackColor=Paper;c.ForeColor=Ink;}
 var lb=c as ListBox;if(lb!=null&&lb.DrawMode!=DrawMode.OwnerDrawFixed){lb.BackColor=Paper;lb.ForeColor=Ink;lb.BorderStyle=BorderStyle.FixedSingle;lb.DrawMode=DrawMode.OwnerDrawFixed;lb.ItemHeight=32;lb.DrawItem+=(s,e)=>{if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Lime:Paper))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,lb.Items[e.Index].ToString(),lb.Font,new Rectangle(e.Bounds.X+10,e.Bounds.Y+6,e.Bounds.Width-20,e.Bounds.Height-8),Ink,TextFormatFlags.EndEllipsis);using(var p=new Pen(Muted)){p.DashStyle=DashStyle.Dot;e.Graphics.DrawLine(p,e.Bounds.X+6,e.Bounds.Bottom-1,e.Bounds.Right-6,e.Bounds.Bottom-1);}};}
 Apply(c);}}
}
public class PixelPage : Form {
 string heading,subtitle; Point drag;bool moving;
 bool Compact {get{return subtitle=="日历安排";}}
 public PixelPage(string title){subtitle=title;heading=title.Contains("日历")?"CALENDAR":title.Contains("KPI")?"MONTHLY KPI":title.Contains("未完")?"BACKLOG":title.Contains("设置")?"SETTINGS":title.Contains("确认")?"NEW TASK":"WORK LOG";SetStyle(ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);FormBorderStyle=FormBorderStyle.None;Padding=title=="日历安排"?new Padding(9,42,9,9):new Padding(14,88,14,30);BackColor=DeskTheme.Paper;AutoScaleMode=AutoScaleMode.None;Font=new Font("Microsoft YaHei UI",9);Shown+=(s,e)=>DeskTheme.Apply(this);}
 protected override void OnPaintBackground(PaintEventArgs e){var g=e.Graphics;g.Clear(DeskTheme.Ink);if(Compact){DeskTheme.Title(g,"CALENDAR",12,11,2);TextRenderer.DrawText(g,"月度安排",new Font("Microsoft YaHei UI",8),new Point(116,12),DeskTheme.Paper);DeskTheme.Frame(g,new Rectangle(5,35,Width-10,Height-40),DeskTheme.Paper,DeskTheme.Paper);TextRenderer.DrawText(g,"×",new Font("Consolas",14),new Point(Width-25,6),DeskTheme.Paper);using(var b=new SolidBrush(DeskTheme.Lime))g.FillRectangle(b,Width-47,13,8,8);return;}using(var p=new Pen(Color.FromArgb(37,43,41)))for(int x=0;x<Width;x+=3)g.DrawLine(p,x,0,x,Height);DeskTheme.Frame(g,new Rectangle(7,70,Width-14,Height-92),DeskTheme.Paper,DeskTheme.Paper);DeskTheme.Title(g,heading,19,15,3);using(var b=new SolidBrush(DeskTheme.Lime))g.FillRectangle(b,20,48,4,12);TextRenderer.DrawText(g,subtitle+"  /  LOCAL WORKSPACE",Font,new Point(32,47),DeskTheme.Paper);TextRenderer.DrawText(g,"×",new Font("Consolas",18),new Point(Width-35,12),DeskTheme.Paper);TextRenderer.DrawText(g,"PIXEL WORKBENCH  /  OFFLINE",new Font("Consolas",8),new Point(17,Height-19),DeskTheme.Muted);using(var b=new SolidBrush(Color.FromArgb(172,104,218))){g.FillRectangle(b,Width-75,18,7,7);g.FillRectangle(b,Width-68,25,7,7);g.FillRectangle(b,Width-61,18,7,7);}}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Y<65){if(e.X>Width-43){Close();return;}moving=true;drag=e.Location;Capture=true;}}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(moving&&e.Button==MouseButtons.Left)Location=new Point(Left+e.X-drag.X,Top+e.Y-drag.Y);}
 protected override void OnMouseUp(MouseEventArgs e){moving=false;Capture=false;base.OnMouseUp(e);}
}
public class PixelDatePicker : Control {
 DateTime date=DateTime.Today;public event EventHandler ValueChanged;
 public DateTime Value{get{return date;}set{date=value;Invalidate();if(ValueChanged!=null)ValueChanged(this,EventArgs.Empty);}}
 public DateTimePickerFormat Format{get;set;} public string CustomFormat{get;set;}public bool ShowUpDown{get;set;}
 public PixelDatePicker(){Height=36;MinimumSize=new Size(150,32);DoubleBuffered=true;Cursor=Cursors.Hand;TabStop=true;Margin=new Padding(4,3,4,10);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent==null?DeskTheme.Paper:Parent.BackColor);DeskTheme.Frame(g,new Rectangle(0,0,Width,Height),DeskTheme.Ink,DeskTheme.Muted);TextRenderer.DrawText(g,"◀",Font,new Rectangle(5,0,25,Height),DeskTheme.Lime,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);TextRenderer.DrawText(g,Value.ToString(ShowUpDown?"yyyy / MM":"yyyy / MM / dd"),new Font("Consolas",11,FontStyle.Bold),new Rectangle(28,0,Width-56,Height),DeskTheme.Paper,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);TextRenderer.DrawText(g,"▶",Font,new Rectangle(Width-30,0,25,Height),DeskTheme.Lime,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.X<30){Value=ShowUpDown?Value.AddMonths(-1):Value.AddDays(-1);return;}if(e.X>Width-30){Value=ShowUpDown?Value.AddMonths(1):Value.AddDays(1);return;}using(var f=new Form{FormBorderStyle=FormBorderStyle.FixedToolWindow,StartPosition=FormStartPosition.Manual,Location=PointToScreen(new Point(0,Height)),ShowInTaskbar=false,TopMost=true}){var calendar=new MonthCalendar{MaxSelectionCount=1,SelectionStart=Value};f.ClientSize=calendar.Size;f.Controls.Add(calendar);calendar.DateSelected+=(s,args)=>{Value=args.Start;f.Close();};f.ShowDialog(FindForm());}}
 protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Left)Value=ShowUpDown?Value.AddMonths(-1):Value.AddDays(-1);if(e.KeyCode==Keys.Right)Value=ShowUpDown?Value.AddMonths(1):Value.AddDays(1);}
}
public static class TaskIcons {
 public static bool Avatars=true;
 static readonly Bitmap[] ReferenceAvatars=LoadReferenceAvatars();
 static Bitmap[] LoadReferenceAvatars(){var result=new Bitmap[6];for(int n=0;n<6;n++){using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("ReferenceAvatar"+n)){if(stream!=null){using(var image=new Bitmap(stream))result[n]=new Bitmap(image);}}}return result;}
 static void Avatar(Graphics g,int n,int x,int y){int[] mapping={4,0,1,3,2,5,0,5};var original=ReferenceAvatars[mapping[n]];if(original!=null){var state=g.Save();g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;g.DrawImage(original,new Rectangle(x-2,y-2,20,20),0,0,original.Width,original.Height,GraphicsUnit.Pixel);g.Restore(state);return;}Color[] hair={Color.FromArgb(211,215,219),Color.FromArgb(182,98,116),Color.FromArgb(77,123,161),Color.FromArgb(125,76,49),Color.FromArgb(75,130,77),Color.FromArgb(218,133,57),Color.FromArgb(56,54,66),Color.FromArgb(143,99,170)};Color[] skin={Color.FromArgb(247,217,180),Color.FromArgb(248,202,166),Color.FromArgb(232,185,143),Color.FromArgb(200,142,99),Color.FromArgb(247,206,164),Color.FromArgb(251,220,172),Color.FromArgb(224,177,142),Color.FromArgb(244,207,180)};Color[] backdrop={Color.FromArgb(166,188,194),Color.FromArgb(207,181,162),Color.FromArgb(175,195,185),Color.FromArgb(208,191,153),Color.FromArgb(187,206,161),Color.FromArgb(208,179,169),Color.FromArgb(175,174,191),Color.FromArgb(202,180,206)};string[][] bangs={new[]{"..hhhhhh..",".hhhhhhhh.","hhh.hhhhhh","hh....hhhh","h......hhh"},new[]{"...hhhh...",".hhhhhhhh.","hhhhhhhhhh","hhh.....hh","hh.......h"},new[]{".hhhhhhhh.","hhhhhhhhhh","hhhhhhhhhh","hh.hhh..hh","h........h"},new[]{"..hhhhh...",".hhhhhhhh.","hhhhhhhhhh","hhhh...hhh","hh......hh"}};using(var b=new SolidBrush(backdrop[n])){for(int r=0;r<16;r++)for(int c=0;c<16;c++){double d=(c-7.5)*(c-7.5)+(r-7.5)*(r-7.5);if(d<=61)g.FillRectangle(b,x+c,y+r,1,1);}}using(var b=new SolidBrush(hair[n])){g.FillRectangle(b,x+3,y+5,10,7);g.FillRectangle(b,x+4,y+3,8,9);}using(var b=new SolidBrush(skin[n])){g.FillRectangle(b,x+4,y+5,8,7);g.FillRectangle(b,x+3,y+7,10,3);g.FillRectangle(b,x+6,y+12,4,2);}using(var b=new SolidBrush(hair[n])){var mask=bangs[n%4];for(int r=0;r<mask.Length;r++)for(int c=0;c<10;c++)if(mask[r][c]=='h')g.FillRectangle(b,x+3+c,y+2+r,1,1);}using(var b=new SolidBrush(DeskTheme.Ink)){g.FillRectangle(b,x+5,y+8,1,2);g.FillRectangle(b,x+10,y+8,1,2);g.FillRectangle(b,x+7,y+11,2,1);}using(var b=new SolidBrush(Color.FromArgb(221,139,122))){g.FillRectangle(b,x+4,y+10,1,1);g.FillRectangle(b,x+11,y+10,1,1);}using(var b=new SolidBrush(Colors[n])){g.FillRectangle(b,x+4,y+13,8,2);g.FillRectangle(b,x+6,y+15,4,1);}using(var b=new SolidBrush(DeskTheme.Ink)){for(int r=0;r<16;r++)for(int c=0;c<16;c++){double d=(c-7.5)*(c-7.5)+(r-7.5)*(r-7.5);if(d>45&&d<=61)g.FillRectangle(b,x+c,y+r,1,1);}}if(n==4){using(var b=new SolidBrush(Color.FromArgb(72,130,71))){g.FillRectangle(b,x+3,y+3,9,2);g.FillRectangle(b,x+1,y+5,13,2);}}}
 static readonly string[][] Shapes={
 new[]{".######.","##cccc##","#cc#ccc#","#cc##cc#","#cc#ccc#","##cccc##",".######.","..#..#.."},
 new[]{"........",".######.","##cccc##","#c#cc#c#","#cc##cc#","#cccccc#",".######.","........"},
 new[]{".######.","##cccc##","########","#cccccc#","#c##ccc#","#cccccc#","#ccc##c#",".######."},
 new[]{".#####..",".#ccc##.",".#c#cc#.",".#cccc#.",".#c##c#.",".#cccc#.",".######.","........"},
 new[]{".######.","##cccc##","#cccccc#","#c#c#cc#","#cccccc#",".###ccc#","...#cc#.","...###.."},
 new[]{".#....#.","########","#cccccc#","########","#c#cc#c#","#cccccc#","#c#cc#c#","########"},
 new[]{"..##.##.",".#cc#cc#",".#cc#cc#","..##.##.",".######.","#cccccc#","#cccccc#","########"},
 new[]{"...##...","..#cc#..",".#cccc#.","#cccccc#","#cc##cc#","#cc##cc#",".######.","..#..#.."}
 };
 static readonly Color[] Colors={Color.FromArgb(182,133,219),Color.FromArgb(235,177,100),Color.FromArgb(125,187,211),Color.FromArgb(218,204,161),Color.FromArgb(155,198,124),Color.FromArgb(231,216,99),Color.FromArgb(226,156,173),Color.FromArgb(181,184,221)};
 public static void Draw(Graphics g,string name,int x,int y,bool complete,bool temporary=false){string text=(name??"").ToLowerInvariant();int n;if(Has(text,"reel","视频","短片","youtube","tiktok"))n=0;else if(Has(text,"邮件","email","mail","联络"))n=1;else if(Has(text,"网站","网页","开发","seo","外链","website"))n=2;else if(Has(text,"访谈","面试","会议","沟通"))n=6;else if(Has(text,"日报","建议","文章","文档","报告","问题","写"))n=3;else if(Has(text,"社媒","发布","粉丝","fb","facebook","推广"))n=4;else if(Has(text,"计划","安排","预约","日程"))n=5;else{uint hash=0;foreach(char c in text)hash=hash*31+c;n=(int)(hash%8);}if(Avatars)Avatar(g,n,x,y);else{using(var edge=new SolidBrush(DeskTheme.Ink))using(var color=new SolidBrush(Colors[n]))for(int r=0;r<8;r++)for(int c=0;c<8;c++){char pixel=Shapes[n][r][c];if(pixel!='.')g.FillRectangle(pixel=='#'?edge:color,x+c*2,y+r*2,2,2);}}if(temporary){using(var rim=new SolidBrush(DeskTheme.Paper))g.FillEllipse(rim,x+9,y-4,11,11);using(var dot=new SolidBrush(Color.FromArgb(211,55,49)))g.FillEllipse(dot,x+10,y-3,9,9);}}
 static bool Has(string text,params string[] words){foreach(string word in words)if(text.Contains(word))return true;return false;}
}
public class TaskActionButton : Button {
 bool hot,down;public TaskActionButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Cursor=Cursors.Hand;Font=new Font("Microsoft YaHei UI",8,FontStyle.Bold);}
 protected override void OnMouseEnter(EventArgs e){hot=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hot=false;down=false;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){down=true;Invalidate();base.OnMouseDown(e);}protected override void OnMouseUp(MouseEventArgs e){down=false;Invalidate();base.OnMouseUp(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(DeskTheme.Paper);var r=new Rectangle(down?1:0,down?1:0,Width-2,Height-2);DeskTheme.Frame(g,new Rectangle(2,2,Width-2,Height-2),DeskTheme.Ink,DeskTheme.Ink);DeskTheme.Frame(g,r,hot?DeskTheme.Lime:DeskTheme.Paper,DeskTheme.Ink);using(var p=new Pen(Color.WhiteSmoke))g.DrawLine(p,r.X+3,r.Y+2,r.Right-4,r.Y+2);using(var p=new Pen(DeskTheme.Muted))g.DrawLine(p,r.X+3,r.Bottom-3,r.Right-3,r.Bottom-3);if(Text=="○"){using(var ring=new Pen(Color.Black,2)){int cx=r.X+r.Width/2,cy=r.Y+r.Height/2;g.DrawEllipse(ring,cx-3,cy-3,6,6);}}else TextRenderer.DrawText(g,Text,Font,r,Text=="✓"?Color.FromArgb(43,128,56):Color.FromArgb(203,48,48),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);}
}
public class SmoothProgress : Control {
 public double Value{get;set;}
 public SmoothProgress(){DoubleBuffered=true;}
 static GraphicsPath Round(RectangleF r,float radius){var path=new GraphicsPath();float d=radius*2;path.AddArc(r.Left,r.Top,d,d,180,90);path.AddArc(r.Right-d,r.Top,d,d,270,90);path.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);path.AddArc(r.Left,r.Bottom-d,d,d,90,90);path.CloseFigure();return path;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(DeskTheme.Paper);g.SmoothingMode=SmoothingMode.AntiAlias;float fraction=(float)(Math.Max(0,Math.Min(100,Value))/100.0);var shell=new RectangleF(2,3,Width-9,Height-6);using(var cap=new SolidBrush(DeskTheme.Ink))g.FillRectangle(cap,Width-7,Height/2f-3,4,6);using(var shape=Round(shell,4)){using(var empty=new SolidBrush(Color.FromArgb(225,226,211)))g.FillPath(empty,shape);var inner=new RectangleF(shell.X+2,shell.Y+2,shell.Width-4,shell.Height-4);if(fraction>0){var state=g.Save();using(var clip=Round(inner,2))g.SetClip(clip);g.SetClip(new RectangleF(inner.X,inner.Y,inner.Width*fraction,inner.Height),CombineMode.Intersect);using(var rainbow=new LinearGradientBrush(inner,Color.Red,Color.Violet,LinearGradientMode.Horizontal)){rainbow.InterpolationColors=new ColorBlend{Colors=new[]{Color.FromArgb(244,93,105),Color.FromArgb(255,171,71),Color.FromArgb(246,222,78),Color.FromArgb(112,209,130),Color.FromArgb(82,194,224),Color.FromArgb(112,137,231),Color.FromArgb(198,119,221)},Positions=new[]{0f,.17f,.33f,.50f,.67f,.83f,1f}};g.FillRectangle(rainbow,inner);}using(var shine=new SolidBrush(Color.FromArgb(72,255,255,255)))g.FillRectangle(shine,inner.X,inner.Y,inner.Width,inner.Height/3);g.Restore(state);}using(var edge=new Pen(DeskTheme.Ink,1.3f))g.DrawPath(edge,shape);}}
}
public class PixelTaskLine : Control {
 public string ProgressText="";public bool Completed,Ended,Temporary;bool hover;
 public PixelTaskLine(){DoubleBuffered=true;TabStop=true;Font=new Font("Microsoft YaHei UI",8,FontStyle.Bold);}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}
