 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(DeskTheme.Ink);Color fill=hover?Color.FromArgb(237,240,209):DeskTheme.Paper;DeskTheme.Frame(g,new Rectangle(1,0,Width-2,Height),fill,DeskTheme.Ink);
 TaskIcons.Draw(g,Text,7,6,Completed,Temporary);
 const int badge=43;TextRenderer.DrawText(g,Text,Font,new Rectangle(27,1,Width-badge-31,Height-2),DeskTheme.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.NoPadding);
 var r=new Rectangle(Width-badge-5,7,badge,15);DeskTheme.Frame(g,r,Completed?DeskTheme.Lime:fill,DeskTheme.Ink);using(var f=new Font(Ended?"Microsoft YaHei UI":"Consolas",8,FontStyle.Bold))TextRenderer.DrawText(g,ProgressText,f,r,Ended?(Completed?Color.FromArgb(43,128,56):Color.FromArgb(203,48,48)):DeskTheme.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.NoPadding);if(Focused)ControlPaint.DrawFocusRectangle(g,new Rectangle(3,2,Width-6,Height-4));}
}
public class PixelDay : Button {
 public bool HasTasks {get;set;} public double Progress {get;set;}
 bool hover; public PixelDay(){SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.AllPaintingInWmPaint,true);Cursor=Cursors.Hand;}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(DeskTheme.Paper);bool selected=BackColor.G>240&&BackColor.R>200&&BackColor.B<80;bool rest=Text.Contains("休息"),csa=Text.Contains("CSA");Color fill=selected?Color.FromArgb(242,250,198):rest?Color.FromArgb(224,224,211):DeskTheme.Paper;DeskTheme.Frame(g,new Rectangle(1,1,Width-2,Height-2),fill,hover?DeskTheme.Lime:DeskTheme.Ink);if(selected)using(var b=new SolidBrush(DeskTheme.Lime))g.FillRectangle(b,4,4,Width-8,18);string[] lines=Text.Split('\n');TextRenderer.DrawText(g,lines[0],new Font("Microsoft YaHei UI",8,FontStyle.Bold),new Rectangle(5,4,Width-8,17),csa?Color.FromArgb(109,66,143):rest?Color.FromArgb(111,113,100):DeskTheme.Ink,TextFormatFlags.EndEllipsis);string body=string.Join("\n",lines,1,lines.Length-1);TextRenderer.DrawText(g,body,Font,new Rectangle(5,23,Width-10,Height-26),DeskTheme.Ink,TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis);if(HasTasks){int trackWidth=Math.Max(1,Width-12);int top=Math.Max(23,Height-11);using(var b=new SolidBrush(DeskTheme.Ink))g.FillRectangle(b,6,top,trackWidth,6);int fillWidth=(int)Math.Round((trackWidth-2)*Math.Max(0,Math.Min(1,Progress)));if(fillWidth>0)using(var b=new SolidBrush(Progress>=1?Color.FromArgb(116,151,42):DeskTheme.Lime))g.FillRectangle(b,7,top+1,fillWidth,4);}if(Focused)ControlPaint.DrawFocusRectangle(g,new Rectangle(3,3,Width-6,Height-6));}
}
